package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
)

type User struct {
	Name string `json:"name"`
	Age  int    `json:"age"`
}

// usersHandler を書く。1つの URL で GET と POST の両方に答える。
// - GET  → Content-Type application/json、200(WriteHeader は書かなくてよい)、
//          map[string][]string で {"users":["washi","taro","hanako"]} を返す
// - POST → ボディを User に Decode。失敗したら 400 "Bad request"。
//          成功したら Content-Type application/json、201、受け取った user の JSON
// - それ以外 → 405 "Method not allowed"
// (サーバー側のログ出力は書かない)
func usersHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method == http.MethodGet {
		w.Header().Set("Content-Type", "application/json")
		response := map[string][]string{
			"users": {"washi", "taro", "hanako"},
		}
		json.NewEncoder(w).Encode(response)

	} else if r.Method == http.MethodPost {
		var user User
		err := json.NewDecoder(r.Body).Decode(&user)
		if err != nil {
			http.Error(w, "Bad request", http.StatusBadRequest)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(user)

	} else {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// ---- ここから下は動作確認用(書き換え不要) ----
var _ = json.Marshal // 雛形のままでもビルドできるようにするための行

// 標準入力の1行 = 1リクエスト。「メソッド」または「メソッド ボディ」の形。
// 各リクエストについて「ステータスコード Content-Type ボディ」を1行で表示する。
func main() {
	sc := bufio.NewScanner(os.Stdin)
	for sc.Scan() {
		method, body, _ := strings.Cut(sc.Text(), " ")
		req := httptest.NewRequest(method, "/users", strings.NewReader(body))
		rec := httptest.NewRecorder()
		usersHandler(rec, req)
		res := rec.Result()
		fmt.Printf("%d %q %q\n", res.StatusCode, res.Header.Get("Content-Type"), rec.Body.String())
	}
}

