package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
)

// 標準入力には1行に1人ずつユーザー名が並んでいる(0人のこともある)。
// map[string][]string を使って {"users":[...]} の形の JSON を作り、
// json.Marshal で文字列にして1行表示する。名前は入力の順番のまま。
// 0人のときは {"users":[]} と表示すること({"users":null} ではない)。
func main() {
	sc := bufio.NewScanner(os.Stdin)
	names := []string{}
	for sc.Scan() {
		names = append(names, sc.Text())
	}
	response := map[string][]string{
		"users": names,
	}
	b, err := json.Marshal(response)
	if err != nil {
		fmt.Println("error")
		return
	}
	fmt.Println(string(b))
}
